@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage<Umbraco.Cms.Core.Models.ContentModel>
@{
    ViewData["Title"] = Model?.Value("heading") ?? "Blog";
}

<!DOCTYPE html>
<html>
<head>
    <title>@ViewData["Title"]</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body>
    <div class="container mx-auto px-4 py-8">
        <h1 class="text-4xl font-bold mb-4">@Model?.Value("heading")</h1>
        <p class="text-lg text-gray-600 mb-8">@Model?.Value("description")</p>

        <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            @{
                var blogPosts = Model?.Children<dynamic>();
                if (blogPosts != null)
                {
                    foreach (var post in blogPosts)
                    {
                        <div class="border rounded-lg overflow-hidden shadow-lg hover:shadow-xl transition">
                            @if (post.Value("featuredImage") != null)
                            {
                                <img src="@post.Value("featuredImage").GetCropUrl(width: 400, height: 250)" alt="@post.Name" class="w-full h-48 object-cover" />
                            }
                            <div class="p-4">
                                <h2 class="text-xl font-bold mb-2">@post.Name</h2>
                                @if (post.Value("publishedDate") != null)
                                {
                                    <p class="text-sm text-gray-500 mb-2">@post.Value<DateTime>("publishedDate").ToString("MMMM dd, yyyy")</p>
                                }
                                <a href="@post.Url()" class="text-blue-600 hover:underline">Read More →</a>
                            </div>
                        </div>
                    }
                }
            }
        </div>
    </div>
    <script src="~/dist/main.js" asp-append-version="true" type="module"></script>
</body>
</html>

