@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage<Umbraco.Cms.Core.Models.ContentModel>
@{
    ViewData["Title"] = Model?.Value("title") ?? "Blog Post";
}

<!DOCTYPE html>
<html>
<head>
    <title>@ViewData["Title"]</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body>
    <div class="container mx-auto px-4 py-8 max-w-2xl">
        <a href="@Model?.Parent()?.Url()" class="text-blue-600 hover:underline mb-4">&larr; Back to Blog</a>

        <h1 class="text-4xl font-bold mb-4">@Model?.Value("title")</h1>

        @if (Model?.Value("publishedDate") != null)
        {
            <p class="text-gray-600 mb-6">Published on @Model.Value<DateTime>("publishedDate").ToString("MMMM dd, yyyy")</p>
        }

        @if (Model?.Value("featuredImage") != null)
        {
            <img src="@Model.Value("featuredImage").GetCropUrl(width: 800, height: 400)" alt="@Model.Value("title")" class="w-full h-96 object-cover rounded-lg mb-8" />
        }

        <div class="prose max-w-none mb-8">
            @Html.Raw(Model?.Value("content"))
        </div>

        <a href="@Model?.Parent()?.Url()" class="text-blue-600 hover:underline">&larr; Back to Blog</a>
    </div>
    <script src="~/dist/main.js" asp-append-version="true" type="module"></script>
</body>
</html>

