@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage<Umbraco.Bench.Umbraco.Models.BlogFrontPage>
@using Umbraco.Cms.Core.Models
@using Umbraco.Extensions

@{
    ViewData["Title"] = Model?.Heading ?? "Blog";
    Layout = null;
}

<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>@ViewData["Title"]</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
    <style>
        body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif; }
        .container { max-width: 1200px; margin: 0 auto; padding: 0 1rem; }
        header { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 3rem 0; text-align: center; }
        header h1 { margin: 0; font-size: 2.5rem; }
        header p { margin: 0.5rem 0 0; opacity: 0.95; }
        .blog-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 2rem; margin: 3rem 0; }
        .blog-card { border-radius: 8px; overflow: hidden; box-shadow: 0 2px 8px rgba(0,0,0,0.1); transition: transform 0.2s, box-shadow 0.2s; text-decoration: none; color: inherit; display: flex; flex-direction: column; }
        .blog-card:hover { transform: translateY(-4px); box-shadow: 0 8px 16px rgba(0,0,0,0.15); }
        .blog-card-image { width: 100%; height: 200px; object-fit: cover; background: #f0f0f0; }
        .blog-card-content { padding: 1.5rem; flex-grow: 1; display: flex; flex-direction: column; }
        .blog-card-title { font-size: 1.25rem; font-weight: 600; margin: 0 0 0.5rem; }
        .blog-card-date { font-size: 0.9rem; color: #666; margin-bottom: 1rem; }
        .blog-card-link { color: #667eea; font-weight: 500; text-decoration: none; margin-top: auto; }
        .blog-card-link:hover { text-decoration: underline; }
    </style>
</head>
<body>
