        <div class="container">
            @{
                var parentPage = Model?.Parent<Umbraco.Bench.Umbraco.Models.BlogFrontPage>();
                if (parentPage != null)
                {
                    <a href="@parentPage.Url()">← Back to Blog</a>
                }
            }
        </div>
    </header>

    <div class="container">
        <div class="post-header">
            <h1 class="post-title">@Model?.Title</h1>
            @if (Model?.PublishedDate != default)
            {
                <p class="post-date">Published on @Model.PublishedDate.ToString("MMMM dd, yyyy")</p>
            }
        </div>

        @if (Model?.FeaturedImage != null)
        {
            var imageUrl = Model.FeaturedImage.MediaWithCrops?.GetCropUrl(width: 800, height: 400) ?? Model.FeaturedImage.Url;
            <img src="@imageUrl" alt="@Model.Title" class="post-image" />
        }

        @if (Model?.Content != null)
        {
            <div class="post-content">
                @Html.Raw(Model.Content)
            </div>
        }

        @{
            var parentPage = Model?.Parent<Umbraco.Bench.Umbraco.Models.BlogFrontPage>();
            if (parentPage != null)
            {
                <a href="@parentPage.Url()" class="back-link">← Back to Blog</a>
            }
        }
    </div>
</body>
</html>

